        if (nx, ny) in unclaimed:
            score += 100
        if (nx, ny) in self_t:
            score += 10

        if man_opp == 1:
            score -= 30

        if best is None or score > best_score:
            best_score = score
            best = [dx, dy]

    if best is None:
        best = [0, 0]
